export function createStudioUI({state,esc,btn,field,openDialog,formDialog,api,endpoint,refresh}) {
  const lines=value=>esc(String(value||'').replace(/\\n/g,'\n'));
  function summary(){const rows=state().production||[];return rows.length?'<details class="company-resources"><summary>Briefings anteriores · '+rows.length+'</summary><p>Reaproveite uma ideia existente na nova tela de criação.</p>'+rows.map(p=>'<div class="detail-actions">'+btn('Ver briefing','studio-production','data-id="'+esc(p.contentId)+'"','secondary')+btn('Criar com este briefing','generate-image','data-id="'+esc(p.contentId)+'"','secondary')+'</div>').join('')+'</details>':'';}
  function detail(p){
    const c=state().records.content.find(c=>c.id===p.contentId);if(!c)return;
    const text=p.decision?.text||p.specification?.exactText?.source||c.caption||'',direction=p.decision?.artDirection||p.specification?.artDirection||c.visualPrompt||'';
    const asset=state().assets.find(a=>a.id===(c.assetId||p.generation?.assetId));
    const preview=asset?'<figure class="generated-image-preview">'+(asset.mime.startsWith('video/')?'<video controls playsinline preload="metadata" src="/api/portal/files/'+encodeURIComponent(asset.id)+'"></video>':'<img src="/api/portal/files/'+encodeURIComponent(asset.id)+'" alt="'+esc(c.title)+'">')+'<figcaption>Arquivo já salvo na Biblioteca</figcaption><a class="p-button secondary" href="/api/portal/files/'+encodeURIComponent(asset.id)+'" download>Baixar arquivo</a></figure>':'';
    openDialog('Briefing · '+c.title,'<div class="studio-production-detail"><p class="dialog-explainer">Use este briefing como ponto de partida. Na próxima tela, escolha o formato e faça seu pedido.</p>'+preview+'<h3>Texto e legenda</h3><p class="prewrap">'+lines(text||'Sem texto definido.')+'</p><h3>Direção visual</h3><p class="prewrap">'+lines(direction||'Descreva a direção visual no próximo pedido.')+'</p>'+(p.specification?.objective?'<h3>Objetivo</h3><p>'+esc(p.specification.objective)+'</p>':'')+'<details class="operation-details"><summary>Histórico do briefing</summary><p>Versão original: '+esc(p.sourceVersion||'não informada')+'</p><p>Origem: '+esc(p.sourceJobId||'registro da empresa')+'</p></details><div class="detail-actions">'+btn('Criar com este briefing',c.format==='video'?'generate-video':'generate-image','data-id="'+esc(p.contentId)+'"')+btn('Materiais da marca','studio-materials','','secondary')+'</div></div>',true);
  }
  function materials(){
    const s=state(),official=s.brandMaterials||{},candidate=(s.production||[]).find(p=>p.candidates?.hash)?.candidates,m=official.confirmedBy?official:candidate||{},org=s.company.id;
    const images=s.assets.filter(a=>a.mime.startsWith('image/')),fonts=s.assets.filter(a=>a.mime.startsWith('font/'));
    const provenance=!official.confirmedBy&&candidate?`<div class="notice-box wide"><strong>Materiais localizados · aguardando sua confirmação</strong><p>Os campos abaixo são sugestões extraídas dos arquivos da EME. Ainda não estão registrados como oficiais.</p><p class="studio-source">${esc(candidate.sources?.logo||'')}<br>${esc(candidate.sources?.font||'')}<br>${esc(candidate.sources?.colors||'')}</p>${images.some(a=>a.id===m.logoAssetId)?`<img class="studio-brand-preview" src="${esc(images.find(a=>a.id===m.logoAssetId).url)}" alt="Logo candidato da EME">`:''}</div>`:'';
    formDialog('Materiais oficiais · '+s.company.name,`<p class="dialog-explainer wide">Confira os arquivos e as cores da empresa antes de confirmar. A confirmação dos materiais não aprova a peça final.</p>`+provenance+field('logoAssetId','Versão oficial do logo','select',m.logoAssetId||'',[['','Selecione o arquivo'],...images.map(a=>[a.id,a.name])],true)+field('fontAssetId','Arquivo da fonte oficial','select',m.fontAssetId||'',[['','Selecione a fonte'],...fonts.map(a=>[a.id,a.name])],true)+field('fontFamily','Família da fonte','text',m.fontFamily||'',[],true)+field('background','Cor de fundo · #RRGGBB','text',m.colors?.background||'',[],true)+field('foreground','Cor do texto · #RRGGBB','text',m.colors?.foreground||'',[],true)+field('accent','Cor de destaque · #RRGGBB','text',m.colors?.accent||'',[],true)+field('confirmed','Confirmo que os arquivos e as cores são os materiais oficiais aprovados desta empresa.','checkbox',false),async d=>{
      if(state().company.id!==org)throw new Error('A empresa ativa mudou. Confira os materiais novamente.');
      await api(endpoint('studio/materials'),'POST',{logoAssetId:d.logoAssetId,fontAssetId:d.fontAssetId,fontFamily:d.fontFamily,colors:{background:d.background,foreground:d.foreground,accent:d.accent},confirmed:d.confirmed===true});await refresh(false);
    },'Salvar materiais oficiais',true);
  }
  return {summary,detail,materials};
}
